// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amt, uint256 value) public {
        vm.assume(amt <= VALUE_CAP);
        // admissible domain: fund more than the withdrawn amount
        amt = bound(amt, 2, type(uint128).max);
        value = bound(value, 1, amt - 1);

        // fund c through its payable receive (owner is this test contract)
        vm.deal(address(this), amt);
        (bool okFund, ) = address(c).call{value: amt}("");
        assertTrue(okFund);

        uint256 cBefore = address(c).balance;
        uint256 ownerBefore = address(this).balance;

        // this test contract is the owner, so it is both caller and recipient
        c.withdraw(value);

        // c's balance decreases by exactly the requested amount, and the
        // owner receives exactly that amount (msg.sender transfer)
        assertTrue(
            address(c).balance == cBefore - value &&
            address(this).balance == ownerBefore + value
        );
    }
    receive() external payable {}
}
